export const missionFor=id=>MISSIONS.find(m=>m.id===id)||MISSIONS[0];
export function missionTuning(index,players=1){
 const level=Math.max(0,Math.min(MISSIONS.length-1,index)),team=Math.max(1,Math.min(4,players));
 return{level:level+1,health:1+level*.12,damage:1+level*.055,speed:1+level*.025,cap:Math.min(48,16+level*2+team*5),batch:4+Math.floor(level/2)+team*2,hold:12+Math.floor(level/3)*2};
}
export function campaignRound(id,seed=38001){
 const spec=missionFor(id),index=MISSIONS.indexOf(spec),entry={x:1300,y:1950},exit={x:1300,y:1900},width=2600,height=2300;
 const points=spec.points.map(([x,y],i)=>({x,y,z:spec.height&&(i%2===0)?spec.height:0}));
 const platforms=points.filter(p=>p.z).map((p,i)=>({x:p.x-180,y:p.y-150,w:360,h:300,z:p.z,kind:'deck',zone:i}));
 const ramps=platforms.map(p=>({x:p.x+20,y:p.y+p.h,w:130,h:270,z:p.z,axis:'y',sign:-1}));
 const obstacles=[{x:0,y:0,w:width,h:65,height:340},{x:0,y:height-65,w:width,h:65,height:340},{x:0,y:65,w:65,h:height-130,height:340},{x:width-65,y:65,w:65,h:height-130,height:340}];
 const layouts={cross:[[450,1150,240,110],[1920,1150,240,110],[1120,500,360,100]],islands:[[1100,650,400,130],[800,1200,170,120],[1700,1250,170,120]],triangle:[[1150,850,300,160],[400,1350,200,100],[2000,1350,200,100]],fortress:[[950,500,170,450],[1480,500,170,450],[1100,1250,400,140]],gantries:[[1050,650,150,650],[1450,650,150,650]],switchback:[[850,850,180,500],[1500,1100,330,120],[2000,1250,150,350]],rings:[[1000,900,600,220],[350,1150,160,280],[2100,1150,160,280]],shards:[[1100,500,190,260],[550,1150,190,170],[1750,1200,210,160]],crown:[[950,650,180,500],[1500,650,180,500],[1100,1250,400,130]]};
 for(const [i,[x,y,w,h]]of layouts[spec.layout].entries())obstacles.push({x,y,w,h,height:45+(i%2)*40,cargo:true});
 if(spec.theme==='spire')obstacles.push({x:1240,y:1010,w:120,h:120,height:500,landmark:'spire'});if(spec.theme==='reactor')obstacles.push({x:1210,y:950,w:180,h:180,height:600,landmark:'reactor'});
 const edge={scrapyard:[120,180,110],spillway:[80,170,85],antenna:[20,20,320],spire:[20,20,320],bunker:[180,200,130],foundry:[70,70,250],rail:[140,280,70],crystal:[170,150,180],reactor:[180,180,290]}[spec.theme];
 for(const x of[130,2470])for(let j=0;j<4;j++)obstacles.push({x:x-edge[0]/2,y:430+j*430-edge[1]/2,w:edge[0],h:edge[1],height:edge[2],landmark:'edge'});
 const portals=[[300,350],[1300,220],[2300,350],[2300,1150],[2200,2000],[400,2000],[300,1150]].map(([x,y])=>({x,y,heading:Math.atan2(1100-y,1300-x)}));
 const route=[{x:1600,y:1800},{x:600,y:1750},{x:600,y:450},{x:2300,y:450},{x:2300,y:1750}],zones=[{...entry,id:0,name:'ENGAGE'},{x:1300,y:1100,id:1,name:spec.name.toUpperCase()},{...exit,id:2,name:'EXTRACT'}];
 return{mode:'operation',raid:true,missionId:spec.id,spec,seed:seed>>>0,name:spec.name.toUpperCase(),terrain:spec.theme.toUpperCase(),sector:index+1,biome:index%3,width,height,entry,exit,heading:-Math.PI/2,rooms:[{x:1300,y:1150,w:width,h:height}],zones,paths:[[entry,...points,exit]],spine:[entry,{x:1300,y:1100},exit],boundaries:[],platforms,ramps,obstacles,portals,points,batteries:[],cells:points,route,reactor:{x:1300,y:1650},estimatedMinutes:spec.minutes};
}
